      RandomGenerator.pick([
        "America/New_York",
        "America/Los_Angeles",
        "Europe/London",
        "Europe/Paris",
        "Asia/Seoul",
        "Asia/Tokyo",
        "Asia/Shanghai",
        "Australia/Sydney",
      ] as const),
    fiscalStartMonth:
      input?.fiscalStartMonth ??
      typia.random<
        number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<12>
      >(),
  };
}

