    name: RandomGenerator.name(),
  };
  await TestValidator.httpError(
    "non-owner cannot update organization",
    403,
    async () => {
      await api.functional.erpHrm.member.organizations.update(
        nonOwnerConnection,
        {
          organizationId: organization.id,
          body: updateBody,
        },
      );
    },
  );
}

