  typia.assert(sortedResult);
  TestValidator.predicate(
    "sorted descending by start_date",
    sortedResult.data[0].startDate >= sortedResult.data[1].startDate &&
      sortedResult.data[1].startDate >= sortedResult.data[2].startDate,
  );
