export async function test_api_project_member_multiple_projects_different_roles(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Authenticate as a member (owner gets 'project:manage' permission)
  const memberConnection: api.IConnection = { host: connection.host };
  const memberAuth = await authorize_member_join(memberConnection, {});
  typia.assert(memberAuth);
  // Step 2: Create first project
  const project1 = await generate_random_erp_hrm_member_projects_create(
    memberConnection,
    {
      body: {
        name: `Project-1-${RandomGenerator.alphaNumeric(8)}`,
        color_code: "#FF5733",
      } satisfies IErpHrmProject.ICreate,
    },
  );
  typia.assert(project1);
  // Step 3: Create second project
  const project2 = await generate_random_erp_hrm_member_projects_create(
    memberConnection,
    {
      body: {
        name: `Project-2-${RandomGenerator.alphaNumeric(8)}`,
        color_code: "#33FF57",
      } satisfies IErpHrmProject.ICreate,
    },
  );
  typia.assert(project2);
  // Step 4: Create an employee in the organization
  const employee = await generate_random_erp_hrm_member_employees_create(
    memberConnection,
    {},
  );
  typia.assert(employee);
  // Step 5: Assign employee to first project with role='member'
  const membership1 =
    await generate_random_erp_hrm_member_projects_members_create(
      memberConnection,
      {
        params: { projectId: project1.id },
        body: {
          employee_id: employee.id,
          role: "member",
        } satisfies IErpHrmProjectMember.ICreate,
      },
    );
  typia.assert(membership1);
  TestValidator.equals(
    "first project membership role",
    membership1.role,
    "member",
  );
  TestValidator.equals(
    "first project membership employee",
    membership1.employee.id,
    employee.id,
  );
  TestValidator.equals(
    "first project membership project",
    membership1.project.id,
    project1.id,
  );
  // Step 6: Assign same employee to second project with role='project_lead'
  const membership2 =
    await generate_random_erp_hrm_member_projects_members_create(
      memberConnection,
      {
        params: { projectId: project2.id },
        body: {
          employee_id: employee.id,
          role: "project_lead",
        } satisfies IErpHrmProjectMember.ICreate,
      },
    );
  typia.assert(membership2);
  TestValidator.equals(
    "second project membership role",
    membership2.role,
    "project_lead",
  );
  TestValidator.equals(
    "second project membership employee",
    membership2.employee.id,
    employee.id,
  );
  TestValidator.equals(
    "second project membership project",
    membership2.project.id,
    project2.id,
  );
  // Step 7: Verify both membership records exist independently with different roles
  TestValidator.notEquals(
    "membership IDs are different",
    membership1.id,
    membership2.id,
  );
  TestValidator.equals(
    "first membership still has member role",
    membership1.role,
    "member",
  );
  TestValidator.equals(
    "second membership still has project_lead role",
    membership2.role,
    "project_lead",
  );
  TestValidator.predicate(
    "same employee in both memberships",
    membership1.employee.id === membership2.employee.id,
  );
  TestValidator.predicate(
    "different projects for each membership",
    membership1.project.id !== membership2.project.id,
  );
}

