  TestValidator.predicate(
    "limit is positive",
    paginatedTimers.pagination.limit >= 1,
  );
  TestValidator.predicate(
    "records is non-negative",
    paginatedTimers.pagination.records >= 0,
  );
  TestValidator.predicate(
    "pages is non-negative",
    paginatedTimers.pagination.pages >= 0,
  );
}

