  TestValidator.equals(
    "invitation status is pending",
    invitation.status,
    "pending",
  );
  TestValidator.equals(
    "invitation email matches",
    invitation.email,
    invitationEmail,
  );
  TestValidator.equals(
    "organization ID matches",
    invitation.organization.id,
    organization.id,
  );
