    return {
      select: {
        id: true,
        name: true,
        description: true,
        logo_image: true,
        currency: true,
        timezone: true,
        fiscal_start_month: true,
        created_at: true,
        owner: ErpHrmMemberAtSummaryTransformer.select(),
        employees: {
          select: {
            erp_hrm_member_id: true,
            role: {
              select: {
                name: true,
              },
            } satisfies Prisma.erp_hrm_rolesFindManyArgs,
          },
        } satisfies Prisma.erp_hrm_employeesFindManyArgs,
