export async function putErpHrmMemberTimersTimerId(props: {
  member: MemberPayload;
  timerId: string & tags.Format<"uuid">;
  body: IErpHrmTimer.IUpdate;
}): Promise<IErpHrmTimer> {
  // Get session to find current organization context
  const session =
    await MyGlobal.prisma.erp_hrm_member_sessions.findUniqueOrThrow({
      where: { id: props.member.session_id },
      select: { erp_hrm_organization_id: true },
    });
  if (session.erp_hrm_organization_id === null) {
    throw new HttpException("No organization context selected", 400);
  }
  // Get employee record for member in current organization
  const employee = await MyGlobal.prisma.erp_hrm_employees.findUniqueOrThrow({
    where: {
      erp_hrm_member_id_erp_hrm_organization_id: {
        erp_hrm_member_id: props.member.id,
        erp_hrm_organization_id: session.erp_hrm_organization_id,
      },
    },
    select: { id: true, status: true },
  });
  // Verify employee is active (not deactivated)
  if (employee.status !== "active") {
    throw new HttpException("Employee is deactivated", 403);
  }
  // Load timer with current project reference
  const timer = await MyGlobal.prisma.erp_hrm_timers.findUniqueOrThrow({
    where: { id: props.timerId },
    select: {
      id: true,
      erp_hrm_employee_id: true,
      erp_hrm_project_id: true,
      deleted_at: true,
    },
  });
  // Verify timer ownership
  if (timer.erp_hrm_employee_id !== employee.id) {
    throw new HttpException("Forbidden", 403);
  }
  // Verify timer is still active (running)
  if (timer.deleted_at !== null) {
    throw new HttpException("Timer is not active", 400);
  }
  // Determine effective project ID
  const effectiveProjectId =
    props.body.erp_hrm_project_id !== undefined
      ? props.body.erp_hrm_project_id
      : timer.erp_hrm_project_id;
  // If project changed, verify employee is a project member
  if (
    props.body.erp_hrm_project_id !== undefined &&
    props.body.erp_hrm_project_id !== timer.erp_hrm_project_id
  ) {
    const membership = await MyGlobal.prisma.erp_hrm_project_members.findFirst({
      where: {
        erp_hrm_employee_id: employee.id,
        erp_hrm_project_id: props.body.erp_hrm_project_id,
        deleted_at: null,
      },
    });
    if (membership === null) {
      throw new HttpException(
        "You are not a member of the specified project",
        400,
      );
    }
  }
  // If task specified, verify it belongs to the project
  if (
    props.body.erp_hrm_task_id !== undefined &&
    props.body.erp_hrm_task_id !== null
  ) {
    const task = await MyGlobal.prisma.erp_hrm_tasks.findFirst({
      where: {
        id: props.body.erp_hrm_task_id,
        project_id: effectiveProjectId,
        deleted_at: null,
      },
    });
    if (task === null) {
      throw new HttpException("Task not found in the specified project", 400);
    }
  }
  // Build update data conditionally
  const data: {
    erp_hrm_project_id?: string;
    erp_hrm_task_id?: string | null;
    description?: string | null;
    updated_at: Date;
  } = {
    updated_at: new Date(),
  };
  if (props.body.erp_hrm_project_id !== undefined) {
    data.erp_hrm_project_id = props.body.erp_hrm_project_id;
  }
  if (props.body.erp_hrm_task_id !== undefined) {
    data.erp_hrm_task_id = props.body.erp_hrm_task_id;
  }
  if (props.body.description !== undefined) {
    data.description = props.body.description;
  }
  // Update timer
  await MyGlobal.prisma.erp_hrm_timers.update({
    where: { id: props.timerId },
    data,
  });
  // Fetch updated timer with relations using transformer select
  const updated = await MyGlobal.prisma.erp_hrm_timers.findUniqueOrThrow({
    where: { id: props.timerId },
    ...ErpHrmTimerTransformer.select(),
  });
  return ErpHrmTimerTransformer.transform(updated);
}

import { IEntity } from "@ORGANIZATION/PROJECT-api/lib/structures/IEntity";
import { IErpHrmContract } from "@ORGANIZATION/PROJECT-api/lib/structures/IErpHrmContract";
import { IPage } from "@ORGANIZATION/PROJECT-api/lib/structures/IPage";
import { IPageIErpHrmContract } from "@ORGANIZATION/PROJECT-api/lib/structures/IPageIErpHrmContract";
import { ArrayUtil } from "@nestia/e2e";
import { HttpException } from "@nestjs/common";
import { Prisma } from "@prisma/sdk";
import jwt from "jsonwebtoken";
import typia, { tags } from "typia";
import { v4 } from "uuid";

import { MyGlobal } from "../MyGlobal";
import { MemberPayload } from "../decorators/payload/MemberPayload";
import { ErpHrmContractAtSummaryTransformer } from "../transformers/ErpHrmContractAtSummaryTransformer";
import { PasswordUtil } from "../utils/PasswordUtil";
import { toISOStringSafe } from "../utils/toISOStringSafe";

export async function patchErpHrmMemberEmployeesEmployeeIdContracts(props: {
  member: MemberPayload;
  employeeId: string & tags.Format<"uuid">;
  body: IErpHrmContract.IRequest;
}): Promise<IPageIErpHrmContract.ISummary> {
  // Get member's session to find organization context
  const session =
    await MyGlobal.prisma.erp_hrm_member_sessions.findUniqueOrThrow({
      where: { id: props.member.session_id },
      select: {
        erp_hrm_organization_id: true,
      },
    });
  // Get member's employee record in the organization
  const memberEmployee = await MyGlobal.prisma.erp_hrm_employees.findFirst({
    where: {
      erp_hrm_member_id: props.member.id,
      erp_hrm_organization_id: session.erp_hrm_organization_id ?? undefined,
      deleted_at: null,
    },
    select: {
      id: true,
      erp_hrm_role_id: true,
    },
  });
  if (memberEmployee === null) {
    throw new HttpException("Employee record not found", 403);
  }
  // Check authorization: own contracts or employee:view permission
  const isOwnContracts = memberEmployee.id === props.employeeId;
  if (!isOwnContracts) {
    // Check for employee:view permission
    const permission = await MyGlobal.prisma.erp_hrm_role_permissions.findFirst(
      {
        where: {
          erp_hrm_role_id: memberEmployee.erp_hrm_role_id,
          permission: "employee:view",
        },
      },
    );
    if (permission === null) {
      throw new HttpException("Forbidden", 403);
    }
  }
  // Verify target employee exists in the same organization
  const targetEmployee = await MyGlobal.prisma.erp_hrm_employees.findFirst({
    where: {
      id: props.employeeId,
      erp_hrm_organization_id: session.erp_hrm_organization_id ?? undefined,
      deleted_at: null,
    },
    select: { id: true },
  });
  if (targetEmployee === null) {
    throw new HttpException("Employee not found", 404);
  }
  // Build date conditions
  const now = new Date();
  // Build start_date range condition
  const startDateConditions: Prisma.DateTimeFilter = {};
  if (
    props.body.startDateFrom !== null &&
    props.body.startDateFrom !== undefined
  ) {
    startDateConditions.gte = new Date(props.body.startDateFrom);
  }
  if (props.body.startDateTo !== null && props.body.startDateTo !== undefined) {
    startDateConditions.lte = new Date(props.body.startDateTo);
  }
  // Build end_date range condition
  const endDateConditions: Prisma.DateTimeNullableFilter = {};
  if (props.body.endDateFrom !== null && props.body.endDateFrom !== undefined) {
    endDateConditions.gte = new Date(props.body.endDateFrom);
  }
  if (props.body.endDateTo !== null && props.body.endDateTo !== undefined) {
    endDateConditions.lte = new Date(props.body.endDateTo);
  }
  // Build where clause
  const whereInput = {
    erp_hrm_employee_id: props.employeeId,
    deleted_at: null,
    // Status filter
    ...(props.body.status === "active"
      ? {
          start_date: { lte: now },
          OR: [{ end_date: null }, { end_date: { gt: now } }],
        }
      : props.body.status === "past"
        ? { end_date: { not: null, lte: now } }
        : props.body.status === "upcoming"
          ? { start_date: { gt: now } }
          : {}),
    // Pay period filter
    ...(props.body.payPeriod !== undefined && props.body.payPeriod !== null
      ? { pay_period: props.body.payPeriod }
      : {}),
    // Start date range filters
    ...(Object.keys(startDateConditions).length > 0
      ? { start_date: startDateConditions }
      : {}),
    // End date range filters
    ...(Object.keys(endDateConditions).length > 0
      ? { end_date: endDateConditions }
      : {}),
  } satisfies Prisma.erp_hrm_contractsWhereInput;
  // Pagination
  const page = props.body.page ?? 1;
  const limit = props.body.limit ?? 20;
  const skip = (page - 1) * limit;
  // Query contracts
  const contracts = await MyGlobal.prisma.erp_hrm_contracts.findMany({
    where: whereInput,
    skip,
    take: limit,
    orderBy: [{ start_date: "desc" }, { created_at: "desc" }],
    ...ErpHrmContractAtSummaryTransformer.select(),
  });
  // Count total records
  const total = await MyGlobal.prisma.erp_hrm_contracts.count({
    where: whereInput,
  });
  // Transform and return
  return {
    data: await ArrayUtil.asyncMap(
      contracts,
      ErpHrmContractAtSummaryTransformer.transform,
    ),
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    } satisfies IPage.IPagination,
  };
}

