   */
  @TypedRoute.Delete(":employeeId")
  public async erase(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("employeeId")
    employeeId: string & tags.Format<"uuid">,
  ): Promise<void> {
    try {
      return await deleteErpHrmMemberEmployeesEmployeeId({
