import { TypedBody, TypedParam, TypedRoute } from "@nestia/core";
import { Controller } from "@nestjs/common";
import typia, { tags } from "typia";

import { IErpHrmTimesheet } from "../../../../api/structures/IErpHrmTimesheet";
import { IPageIErpHrmTimesheet } from "../../../../api/structures/IPageIErpHrmTimesheet";
import { MemberAuth } from "../../../../decorators/MemberAuth";
import { MemberPayload } from "../../../../decorators/payload/MemberPayload";
import { getErpHrmMemberTimesheetsTimesheetId } from "../../../../providers/getErpHrmMemberTimesheetsTimesheetId";
import { patchErpHrmMemberTimesheets } from "../../../../providers/patchErpHrmMemberTimesheets";
import { postErpHrmMemberTimesheets } from "../../../../providers/postErpHrmMemberTimesheets";
import { postErpHrmMemberTimesheetsTimesheetIdApprove } from "../../../../providers/postErpHrmMemberTimesheetsTimesheetIdApprove";
import { postErpHrmMemberTimesheetsTimesheetIdReject } from "../../../../providers/postErpHrmMemberTimesheetsTimesheetIdReject";
import { postErpHrmMemberTimesheetsTimesheetIdSubmit } from "../../../../providers/postErpHrmMemberTimesheetsTimesheetIdSubmit";
import { putErpHrmMemberTimesheetsTimesheetId } from "../../../../providers/putErpHrmMemberTimesheetsTimesheetId";

@Controller("/erpHrm/member/timesheets")
export class ErphrmMemberTimesheetsController {
  /**
   * Create a new draft timesheet for the authenticated employee for a specific work week.
   *
   * This operation allows an employee to create a new timesheet for a specific week period, defined by a Monday start date and Sunday end date. Upon creation, the timesheet is set to 'draft' status, allowing the employee to review and modify the included timelogs before submission for approval.
   *
   * The system automatically aggregates all existing timelogs for the employee within the specified week period and calculates the total hours. These timelogs are associated with the timesheet through the timesheet_timelogs junction table, enabling the employee to subsequently add or remove timelogs before final submission.
   *
   * **Business Rules:**
   * - Each employee can have only one timesheet per week (enforced by unique constraint on employee_id and week_start_date).
   * - Deactivated employees cannot create timesheets - the operation will be rejected with a 403 Forbidden error.
   * - The week must be a valid Monday-to-Sunday period.
   * - If a timesheet already exists for the same employee and week, the operation will fail with a 409 Conflict error.
   *
   * **Related Operations:**
   * - PATCH /timesheets/{timesheetId}/timelogs — Add or remove timelogs from a draft timesheet
   * - POST /timesheets/{timesheetId}/submit — Submit the timesheet for approval
   * - GET /timesheets/{timesheetId} — Retrieve detailed timesheet information
   *
   * @param connection
   * @param body Week period for the new timesheet. Must specify a valid Monday start date and Sunday end date.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification 1. Extract the authenticated member's ID from the JWT session token.
   * 2. Look up the employee record for the authenticated member within the current organization context (using organization_id from session).
   * 3. Verify the employee status is 'active' - reject with 403 Forbidden if employee is deactivated.
   * 4. Validate that week_start_date is a Monday and week_end_date is the following Sunday (7-day week period).
   * 5. Check if a timesheet already exists for this employee and week_start_date (unique constraint).
   * 6. If duplicate exists, reject with 409 Conflict error.
   * 7. Calculate total_hours by summing duration/60 for all timelogs belonging to this employee within the date range [week_start_date, week_end_date].
   * 8. Create the timesheet record with:
   *    - employee_id = current employee's ID
   *    - week_start_date and week_end_date from request
   *    - status = 'draft'
   *    - total_hours = calculated sum
   *    - reviewer_id, submitted_at, reviewed_at, rejection_reason = null
   * 9. Create associations in erp_hrm_timesheet_timelogs for all matching timelogs.
   * 10. Return the created timesheet with all fields.
   *
   * Edge cases:
   * - Employee not found in organization: 404 Not Found
   * - Deactivated employee: 403 Forbidden
   * - Invalid week (not Mon-Sun): 400 Bad Request
   * - Duplicate timesheet for same week: 409 Conflict
   * - Organization context missing: 400 Bad Request
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post()
  public async create(
    @MemberAuth()
    member: MemberPayload,
    @TypedBody()
    body: IErpHrmTimesheet.ICreate,
  ): Promise<IErpHrmTimesheet> {
    try {
      return await postErpHrmMemberTimesheets({
        member,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve a filtered and paginated list of timesheets.
   *
   * This operation provides timesheet visibility based on user permissions. Regular employees can view only their own timesheets, while users with time approval or time view all permissions can access all timesheets within the organization.
   *
   * The timesheet list displays weekly time aggregations with key information including the week period (Monday to Sunday), current status, total hours logged, submission and review timestamps, and reviewer details for approved or rejected timesheets.
   *
   * Supports filtering by status to focus on draft, submitted, approved, or rejected timesheets. Date range filtering allows viewing timesheets for specific weeks or periods. Results are paginated with configurable page sizes.
   *
   * The status field indicates the workflow state: draft timesheets are editable by the employee, submitted timesheets await manager approval, approved timesheets are locked and cannot be modified, and rejected timesheets have been returned to draft status with documented reasons.
   *
   * Related operations: Use GET /timesheets/{timesheetId} to retrieve detailed information about a specific timesheet. Use POST /timesheets to create a draft timesheet for a specific week. Use PUT /timesheets/{timesheetId}/submit to submit a draft for approval.
   *
   * @param connection
   * @param body Search criteria including status filter, date range, and pagination parameters
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Query erp_hrm_timesheets table with pagination and filtering.
   *
   * Authorization logic:
   * 1. If user has time:view_all permission: return all timesheets in organization
   * 2. If user has time:approve permission: return all timesheets in organization (for approval workflow)
   * 3. Otherwise: return only timesheets belonging to the current employee
   *
   * Apply filters:
   * - Filter by status array (draft, submitted, approved, rejected)
   * - Filter by date range (week_start_date between from and to dates)
   *
   * Join with:
   * - erp_hrm_employees to get employee information
   * - erp_hrm_members for reviewer information if present
   * - erp_hrm_timesheet_timelogs count for timelog count
   *
   * Calculate pagination:
   * - Use cursor-based pagination for large result sets
   * - Return page info with total count
   *
   * Sort by week_start_date descending by default.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async index(
    @MemberAuth()
    member: MemberPayload,
    @TypedBody()
    body: IErpHrmTimesheet.IRequest,
  ): Promise<IPageIErpHrmTimesheet.ISummary> {
    try {
      return await patchErpHrmMemberTimesheets({
        member,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve detailed information for a specific timesheet identified by its unique identifier.
   *
   * This operation allows employees to view their own timesheets and users with the time:view_all permission to view any timesheet in the organization. The response includes the complete timesheet data encompassing the weekly period (Monday through Sunday), current workflow status, total hours calculated from all included timelogs, submission and review timestamps, and the list of associated timelog entries.
   *
   * The timesheet status determines what actions can be taken: draft timesheets can be modified by the employee, submitted timesheets await manager approval, approved timesheets are locked and cannot be modified, and rejected timesheets return to draft status with an optional rejection reason for the employee to address.
   *
   * For approved timesheets, all included timelogs become locked and cannot be edited or deleted, preserving the integrity of approved work records. The reviewer information is included for timesheets that have been approved or rejected, identifying who performed the review action.
   *
   * Authorization is enforced based on employee ownership or the time:view_all permission. Employees can only access their own timesheets unless they have been granted the time:view_all permission, which provides visibility into all employees' timesheets for oversight and reporting purposes.
   *
   * @param connection
   * @param timesheetId Unique identifier of the timesheet to retrieve
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Query the erp_hrm_timesheets table by primary key id, joining with erp_hrm_employees to verify organization context and ownership. Include related erp_hrm_timesheet_timelogs and their associated erp_hrm_timelogs for the timelog entries. Verify authorization: the requesting user must either own the timesheet (via employee relationship) or have time:view_all permission. Return 404 if timesheet not found or not accessible. Return 403 if user lacks permission to view this timesheet. The response includes the complete timesheet with all timelogs for the week, status information, and review details if applicable.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get(":timesheetId")
  public async at(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("timesheetId")
    timesheetId: string & tags.Format<"uuid">,
  ): Promise<IErpHrmTimesheet> {
    try {
      return await getErpHrmMemberTimesheetsTimesheetId({
        member,
        timesheetId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Update a timesheet's timelog associations.
   *
   * This operation allows employees to modify which timelogs are included in their timesheet. Only timesheets in draft or rejected status can be updated; submitted and approved timesheets are immutable per the Submitted Timesheet Immutability rule.
   *
   * When a timesheet is in rejected status, updating it keeps the status as draft (rejected timesheets return to draft status per the rejection workflow), allowing the employee to revise and resubmit for approval.
   *
   * All timelogs specified must belong to the same employee and fall within the timesheet's weekly period (Monday to Sunday). Timelogs that are already part of another submitted or approved timesheet cannot be added.
   *
   * The total hours are automatically recalculated based on the sum of all included timelog durations divided by 60 minutes.
   *
   * This operation requires the authenticated member to be the owner of the employee record associated with the timesheet. Users with time:manage permission cannot modify timesheet contents directly - they must reject submitted timesheets and have the employee revise them.
   *
   * Related operations:
   * - GET /timesheets/{timesheetId} - View timesheet details
   * - PATCH /timesheets - List and filter timesheets
   * - POST /timesheets - Create a new draft timesheet
   *
   * @param connection
   * @param timesheetId Unique identifier of the timesheet to update (UUID format)
   * @param body Updated timesheet data including the list of timelog IDs to associate with this timesheet
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Update the timelog associations of a timesheet. The service layer must:
   *
   * 1. Validate the timesheet exists and belongs to the current organization context
   * 2. Verify the authenticated member owns the employee record (employee_id matches the member's employee in current organization)
   * 3. Check timesheet status is 'draft' or 'rejected' - reject with 403 if 'submitted' or 'approved'
   * 4. For each timelog ID in the request:
   *    - Verify timelog exists and belongs to the same employee
   *    - Verify timelog date falls within the timesheet's week (week_start_date to week_end_date)
   *    - Verify timelog is not already part of another submitted/approved timesheet
   * 5. Clear existing timelog associations and create new associations in erp_hrm_timesheet_timelogs
   * 6. Recalculate total_hours as sum of all associated timelog durations / 60
   * 7. If status was 'rejected', keep it as 'draft' (employee must resubmit after revision)
   * 8. Return updated timesheet with timelog details
   *
   * Edge cases:
   * - Empty timelog array: Allowed for draft timesheets, but cannot be submitted
   * - Timelog belongs to different employee: Reject with 400
   * - Timelog outside week range: Reject with 400
   * - Timelog already in approved timesheet: Reject with 400
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Put(":timesheetId")
  public async update(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("timesheetId")
    timesheetId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IErpHrmTimesheet.IUpdate,
  ): Promise<IErpHrmTimesheet> {
    try {
      return await putErpHrmMemberTimesheetsTimesheetId({
        member,
        timesheetId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Submit a draft timesheet for manager approval.
   *
   * This operation transitions a timesheet from 'draft' to 'submitted' status, making it available for review by users with time:approve permission. Once submitted, the timesheet becomes locked and the employee cannot modify its contents or the associated timelogs.
   *
   * The submission process validates several business rules before allowing the status transition. The timesheet must contain at least one timelog entry. Only one timesheet per employee per week can be in 'submitted' or 'approved' status at any time. The employee submitting the timesheet must be active within their organization.
   *
   * After successful submission, the timesheet awaits approval from a manager or designated reviewer. If the timesheet is rejected, it returns to 'draft' status allowing the employee to make modifications and resubmit. Approved timesheets permanently lock all included timelogs, preventing any further modifications.
   *
   * Related operations:
   * - POST /timesheets — Create a new draft timesheet for a specific week
   * - PATCH /timesheets/{timesheetId}/timelogs — Add or remove timelogs from a draft timesheet
   * - POST /timesheets/{timesheetId}/approve — Approve a submitted timesheet (requires time:approve permission)
   * - POST /timesheets/{timesheetId}/reject — Reject a submitted timesheet with reason (requires time:approve permission)
   *
   * @param connection
   * @param timesheetId Unique identifier of the timesheet to submit. The timesheet must be owned by the authenticated employee and have 'draft' status.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Implementation steps:
   *
   * 1. Validate path parameter timesheetId is a valid UUID
   *
   * 2. Query erp_hrm_timesheets table to find the timesheet:
   *    - WHERE id = timesheetId AND deleted_at IS NULL
   *    - Include employee relation to verify employee status
   *
   * 3. Authorization checks:
   *    - Verify the authenticated member has an employee record in the same organization
   *    - Verify the timesheet belongs to this employee (employee_id matches)
   *    - Verify employee.status is 'active' (not deactivated)
   *
   * 4. Status validation:
   *    - Verify timesheet.status === 'draft'
   *    - If status is not 'draft', return 400 error with appropriate message
   *
   * 5. Empty timesheet validation:
   *    - Count records in erp_hrm_timesheet_timelogs WHERE timesheet_id = timesheetId
   *    - If count is 0, return 400 error: 'Timesheet must contain at least one timelog'
   *
   * 6. Duplicate week submission prevention:
   *    - Query erp_hrm_timesheets WHERE employee_id = currentEmployeeId AND week_start_date = timesheet.week_start_date AND id != timesheetId AND status IN ('submitted', 'approved') AND deleted_at IS NULL
   *    - If any record exists, return 400 error: 'Another timesheet for this week is already submitted or approved'
   *
   * 7. Update the timesheet:
   *    - SET status = 'submitted'
   *    - SET submitted_at = current_timestamp
   *    - SET updated_at = current_timestamp
   *
   * 8. Return the updated timesheet with status 'submitted' and submitted_at populated
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post(":timesheetId/submit")
  public async submit(
    @MemberAuth()
    member: MemberPayload,
    @TypedParam("timesheetId")
    timesheetId: string & tags.Format<"uuid">,
  ): Promise<IErpHrmTimesheet> {
    try {
      return await postErpHrmMemberTimesheetsTimesheetIdSubmit({
        member,
        timesheetId,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Approve a submitted timesheet for an employee's weekly work record.
   *
   * This operation allows managers or users with time approval permissions to review and accept a submitted timesheet. Approval indicates that the work hours documented in the timesheet have been reviewed and accepted as accurate.
   *
   * When a timesheet is approved, its status transitions from 'submitted' to 'approved'. The system records which user performed the approval and when. All timelog entries included in the approved timesheet become locked and cannot be modified or deleted by any user, including those with time management permissions. This ensures the integrity of approved work records for payroll, billing, and compliance purposes.
   *
   * **Prerequisites**:
   * - The timesheet must exist and belong to the current organization
   * - The timesheet must be in 'submitted' status
   * - The authenticated user must have 'time:approve' permission
   *
   * **Related Operations**:
   * - POST /timesheets/{timesheetId}/reject — Reject a submitted timesheet with a reason
   * - GET /timesheets — View list of timesheets (to find submitted timesheets awaiting approval)
   * - GET /timesheets/{timesheetId} — View detailed timesheet before approval
   *
   * @param connection
   * @param timesheetId Unique identifier of the timesheet to approve. The timesheet must be in 'submitted' status and belong to the current organization.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor member
   * @x-autobe-specification Implementation Steps:
   *
   * 1. **Authorization Check**: Verify the authenticated user has 'time:approve' permission in the current organization context.
   *
   * 2. **Timesheet Lookup**: Query erp_hrm_timesheets table by timesheetId, ensuring the timesheet belongs to the current organization (via employee -> organization relationship).
   *
   * 3. **Status Validation**: Verify the timesheet status is 'submitted'. If not, reject with error indicating only submitted timesheets can be approved.
   *
   * 4. **Approval Action**: Update the timesheet record:
   *    - Set status to 'approved'
   *    - Set reviewer_id to the authenticated user's member ID
   *    - Set reviewed_at to current timestamp
   *    - Update updated_at timestamp
   *
   * 5. **Timelog Locking**: Query all timelogs associated with this timesheet via erp_hrm_timesheet_timelogs junction table. These timelogs become implicitly locked - the system must enforce this through business logic in timelog edit/delete operations.
   *
   * 6. **Response**: Return the updated timesheet entity including:
   *    - id, employee_id, reviewer_id
   *    - week_start_date, week_end_date
   *    - status ('approved')
   *    - total_hours
